<script setup lang="ts">
import {queryV2Tools,routeOptimizationEnabled,travelEnabled} from '../services/v2Tools'
import {cloudTrips,tripsState,syncTrips,saveCloudTrip,deleteCloudTrip} from '../services/remoteTrips'
import {useRouter} from 'vue-router'
import {computed,ref,watch} from 'vue'
import {showToast,showConfirmDialog} from 'vant'
import {store,currentPets,image} from '../stores/community'
import {scenes,outingCities,recommendOuting,todayInShanghai,validateTrip} from '../services/trips'
import type {Trip} from '../types'
const router=useRouter(),saving=ref(false),deleting=ref('')
const pets=computed(()=>currentPets.value)
const petIds=ref(pets.value.slice(0,2).map(p=>p.id)),sceneIds=ref<string[]>([]),date=ref(todayInShanghai(new Date(Date.now()+86400000))),time=ref('09:00'),city=ref('上海'),checklist=ref<string[]>([]),editing=ref(''),history=ref(false),query=ref(''),searchOpen=ref(false)
const items=['疫苗本','牵引绳','折叠水碗','清洁袋','宠物零食']
const selectedPets=computed(()=>pets.value.filter(p=>petIds.value.includes(p.id)))
const selectedScenes=computed(()=>scenes.filter(s=>sceneIds.value.includes(s.id)))
const weather=ref<{city:string;condition:string;temperature:string;updatedAt:string}>()
const weatherLoading=ref(false),weatherError=ref(''),weatherRefresh=ref(0)
const cityOptions=computed(()=>city.value&&!outingCities.includes(city.value)?[city.value,...outingCities]:outingCities)
const recommendation=computed(()=>recommendOuting(
 sceneIds.value,time.value,selectedPets.value.length,date.value===todayInShanghai()?weather.value?.condition:undefined,
))
const stops=computed(()=>recommendation.value.stops)
watch([city,weatherRefresh],async ([selectedCity],_,onCleanup)=>{
 let current=true
 onCleanup(()=>{current=false})
 weather.value=undefined
 weatherError.value=''
 if(!travelEnabled||!selectedCity)return
 weatherLoading.value=true
 try{
  const result=await queryV2Tools({action:'weather',city:selectedCity})
  if(!current)return
  if(result.weather)weather.value=result.weather
  else weatherError.value=result.error||'暂时无法查询实况天气'
 }catch{
  if(current)weatherError.value='暂时无法查询实况天气'
 }finally{
  if(current)weatherLoading.value=false
 }
},{immediate:true})
const visibleScenes=computed(()=>scenes.filter(s=>(s.name+s.note).includes(query.value.trim())))
watch(pets,()=>{petIds.value=petIds.value.filter(id=>pets.value.some(p=>p.id===id))})
function toggle(list:string[],id:string){const index=list.indexOf(id);if(index>=0)list.splice(index,1);else list.push(id)}
async function save(){if(saving.value)return;if(!currentPets.value.length){showToast('请先添加你的宠物档案');router.push({path:'/pets',query:{add:'1',next:'/outing'}});return}const error=validateTrip(selectedPets.value.map(p=>p.id),sceneIds.value,date.value,time.value);if(error){showToast(error);return}if(!city.value.trim()){showToast('请填写出行城市');return}const now=Date.now(),old=store.trips.find(t=>t.id===editing.value);if(editing.value&&!old){showToast('行程不存在，请刷新列表后重试');return}const trip:Trip={id:old?.id||crypto.randomUUID(),city:city.value.trim(),date:date.value,time:time.value,petIds:selectedPets.value.map(p=>p.id),petNames:selectedPets.value.map(p=>p.name),sceneIds:[...sceneIds.value],stops:stops.value.map(s=>({...s})),checklist:[...checklist.value],demoPets:false,createdAt:old?.createdAt||now,updatedAt:now};saving.value=true;try{if(cloudTrips)await saveCloudTrip(trip,!!editing.value);else if(old)store.trips.splice(store.trips.indexOf(old),1,trip);else store.trips.unshift(trip);editing.value='';showToast(cloudTrips?'行程已保存到云端':'行程已保存到本机');history.value=true}catch(e){showToast((e as Error).message||'保存失败，请重试')}finally{saving.value=false}}
function edit(trip:Trip){editing.value=trip.id;city.value=trip.city;date.value=trip.date;time.value=trip.time;petIds.value=trip.petIds.filter(id=>pets.value.some(p=>p.id===id));sceneIds.value=[...trip.sceneIds];checklist.value=[...trip.checklist];history.value=false;if(petIds.value.length!==trip.petIds.length)showToast('部分宠物档案已变更，请重新选择同行宠物');window.scrollTo({top:0,behavior:'smooth'})}
function cancelEdit(){editing.value='';petIds.value=pets.value.slice(0,2).map(p=>p.id);sceneIds.value=[];date.value=todayInShanghai(new Date(Date.now()+86400000));time.value='09:00';checklist.value=[]}
async function remove(id:string){if(deleting.value)return;try{await showConfirmDialog({title:'删除行程',message:cloudTrips?'确定删除这份云端行程吗？删除后无法恢复。':'确定删除这份本地行程吗？'})}catch{return}deleting.value=id;try{if(cloudTrips)await deleteCloudTrip(id);else store.trips=store.trips.filter(t=>t.id!==id);if(editing.value===id)cancelEdit();showToast('行程已删除')}catch(e){showToast((e as Error).message||'删除失败，请重试')}finally{deleting.value=''}}
function download(trip:Trip){const text=`PawsUp 出行清单\n${trip.city} · ${trip.date} ${trip.time}\n同行：${trip.petNames.join('、')}${trip.demoPets?'（示例宠物）':''}\n路线示意：出发地 → ${trip.stops.map(s=>s.title).join(' → ')}\n已准备：${trip.checklist.join('、')||'尚未勾选'}\n待准备：${items.filter(i=>!trip.checklist.includes(i)).join('、')||'已全部准备'}\n行程安排未计路上耗时。出发前请核实地点、天气与携宠规则。`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='PawsUp_'+trip.date+'_出行清单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><main class="outing-page"><header class="outing-top"><div><h1>出行</h1><p>带上毛孩子，挑个好天气出发</p></div><div><button aria-label="搜索出行场景" @click="searchOpen=!searchOpen"><van-icon name="search"/></button><button aria-label="我的行程" @click="history=true"><van-icon name="calendar-o"/></button></div></header>
<div v-if="tripsState.error" class="trip-sync-error" role="alert">行程加载失败：{{tripsState.error}}<button @click="syncTrips().catch(()=>{})">重新加载</button></div><section class="weather-banner" aria-live="polite">
  <van-icon name="location-o" class="weather-icon"/>
  <div>
    <strong>{{weather ? weather.city+' · '+weather.condition+' · '+weather.temperature+'℃' : city+' · 实况天气'}}</strong>
    <p v-if="weather">更新于 {{weather.updatedAt}} · 当前实况</p>
    <p v-else-if="weatherLoading">正在查询天气…</p>
    <p v-else>{{weatherError||'实况天气暂不可用'}}</p>
  </div>
  <button v-if="weatherError&&travelEnabled" class="weather-retry" type="button" @click="weatherRefresh++">重试</button>
</section>
<section class="outing-card"><div class="outing-head"><div><h2>谁一起出发？</h2><p>可同时选择多只毛孩子</p></div><RouterLink to="/pets">管理宠物 ›</RouterLink></div><p v-if="!currentPets.length" class="sample-note">还没有宠物档案，请先添加你的毛孩子。</p><div class="companion-grid"><button v-for="pet in pets" :key="pet.id" role="switch" :aria-checked="petIds.includes(pet.id)" :aria-label="pet.name" @click="toggle(petIds,pet.id)"><img :src="pet.photo" :alt="pet.name"/><span><b>{{pet.name}}</b><small>{{pet.breed||pet.species}}</small><em>{{petIds.includes(pet.id)?'✓ 同行':'未选择'}}</em></span></button></div></section>
<section class="outing-card"><div class="outing-head"><div><h2>想去哪儿玩？</h2><p>点选场景，可同时选几个</p></div><small>已选 {{sceneIds.length}} 项</small></div><van-search v-if="searchOpen" v-model="query" placeholder="搜索公园、咖啡、露营…" shape="round"/><div class="scene-grid"><button v-for="scene in visibleScenes" :key="scene.id" role="switch" :aria-label="scene.name" :aria-checked="sceneIds.includes(scene.id)" :style="{background:scene.color}" @click="toggle(sceneIds,scene.id)"><img :src="image('trip-'+scene.id)" :alt="scene.name"/><span v-if="sceneIds.includes(scene.id)" class="scene-check">已选</span><b>{{scene.name}}</b><small>{{scene.note}}</small></button></div><van-empty v-if="!visibleScenes.length" description="没有匹配场景，换个关键词试试"/></section>
<section class="outing-card plan-card"><div class="outing-head"><div><h2>行程规划</h2><p>选好时间和场景，整理出行安排</p></div><span class="draft-badge">{{editing?'编辑中':'草稿'}}</span></div><label class="city-field">出行城市<select v-model="city" aria-label="出行城市"><option v-for="option in cityOptions" :key="option" :value="option">{{option}}</option></select></label><div class="date-grid"><label>出行日期<input v-model="date" aria-label="出行日期" type="date" :min="todayInShanghai()" required/></label><label>出发时间<input v-model="time" aria-label="出发时间" type="time" required/></label></div><dl class="plan-summary"><div><dt>同行宠物</dt><dd>{{selectedPets.map(p=>p.name).join(' · ')||'尚未选择'}}</dd></div><div><dt>已选场景</dt><dd>{{selectedScenes.map(s=>s.name).join(' · ')||'尚未选择'}}</dd></div></dl><div class="route-heading"><h3>推荐路线</h3><span>交通与行程建议</span></div>
<div v-if="stops.length" class="transport-advice"><strong>{{recommendation.transport}}</strong><p>{{recommendation.reason}}</p></div>
<ol v-if="stops.length" class="outing-route"><li><span>1</span><div><b>出发地 · {{city||'待填写'}}</b><small>{{date}} {{time}} 出发</small></div></li><li v-for="(stop,index) in stops" :key="stop.title"><span>{{index+2}}</span><div><b>{{stop.title}}</b><small>{{stop.note}}</small></div></li></ol><div v-else class="route-empty">选择一个出行场景，就能看到交通建议和行程安排。</div><RouterLink v-if="routeOptimizationEnabled && stops.length" class="navigation-link" :to="{path:'/travel',query:{city}}">填入具体地址，优化驾车路线 ›</RouterLink><h3>出发前清单</h3><div class="packing-list"><button v-for="item in items" :key="item" :aria-pressed="checklist.includes(item)" @click="toggle(checklist,item)"><van-icon :name="checklist.includes(item)?'checked':'circle'"/> {{item}}</button></div><van-button block round color="linear-gradient(135deg,#e85d3b,#c2410c)" :loading="saving" :disabled="!!tripsState.error||tripsState.loading" @click="save">{{editing?'保存修改':'规划并保存行程'}}</van-button><button v-if="editing" class="cancel-edit" @click="cancelEdit">取消编辑</button><p class="plan-note">行程安排按场景估算，不含路上耗时。出发前请确认具体地点与携宠规则。</p></section><button class="history-entry" @click="history=true"><van-icon name="calendar-o"/> 我的行程 <span>{{store.trips.length}} 份 ›</span></button><footer>{{cloudTrips?'行程按账号保存在云端，仅自己可见。':'行程仅保存在当前浏览器。'}}</footer>
<van-popup v-model:show="history" position="bottom" round closeable><section class="trip-history"><h2>我的行程</h2><p>已保存 {{store.trips.length}} 份{{cloudTrips?'云端':'本地'}}行程</p><button v-if="cloudTrips" class="cancel-edit" :disabled="tripsState.loading" @click="syncTrips().catch(()=>{})">{{tripsState.loading?'正在同步…':'刷新云端行程'}}</button><p v-if="tripsState.error" role="alert">{{tripsState.error}}</p><van-empty v-if="!store.trips.length&&!tripsState.error&&!tripsState.loading" description="还没有行程，先规划一次出发吧"/><article v-for="trip in store.trips" :key="trip.id" class="saved-trip"><span class="saved-tag">{{trip.demoPets?'示例宠物行程':'已保存'}}</span><h3>{{trip.city}} · {{trip.date}}</h3><p>{{trip.time}} 出发 · {{trip.petNames.join('、')}}</p><p class="saved-route">出发地 → {{trip.stops.map(s=>s.title).join(' → ')}}</p><small>行前清单 {{trip.checklist.length}} / {{items.length}} 已准备</small><div class="saved-actions"><button @click="edit(trip)">修改</button><button @click="download(trip)">下载清单</button><button :disabled="!!deleting" @click="remove(trip.id)">删除</button></div></article></section></van-popup></main></template>
<style scoped>
.weather-retry{margin-left:auto;border:0;background:transparent;color:#2459b3;white-space:nowrap;font:inherit}
.transport-advice{padding:12px;border-radius:14px;background:#eef2ff;color:#40335b}
.transport-advice p{margin:4px 0 0;font-size:12px}
.navigation-link{color:#2459b3;font-size:12px}

.trip-sync-error{padding:12px;border-radius:14px;background:#fff5eb;color:#9a6239;font-size:12px;overflow-wrap:anywhere}.trip-sync-error button{margin-left:8px;border:0;background:transparent;color:#2563eb;font:inherit}

.outing-page{display:flex;flex-direction:column;gap:16px;padding:16px 18px 112px;color:#2b2340;font-size:14px}.outing-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.outing-top h1{font-size:24px;letter-spacing:0}.outing-top p{font-size:12px;color:#6b6086;margin-top:3px}.outing-top>div:last-child{display:flex;gap:8px}.outing-top button{width:42px;height:42px;border-radius:50%;border:1px solid white;background:#ffffffb8;font-size:22px;color:#2b2340;display:grid;place-items:center}.weather-banner{display:flex;align-items:center;gap:10px;padding:14px 12px;border-radius:22px;background:#dcebffb8;border:1px solid white}.weather-icon{font-size:27px;color:#b58850}.weather-banner strong{font-size:12px}.weather-banner p{font-size:10px;color:#6b6086;line-height:1.5;margin-top:3px}.demo-badge{margin-left:auto;font-size:10px;color:#6b6086;white-space:nowrap}.outing-card{display:flex;flex-direction:column;gap:14px;padding:16px;border-radius:24px;border:1px solid #ffffffe6;background:#ffffffb8;box-shadow:0 12px 32px #9682c824}.outing-head{display:flex;align-items:center;justify-content:space-between;gap:6px}.outing-head h2{font-size:18px;font-weight:600}.outing-head p{font-size:11px;color:#6b6086;line-height:1.5;margin-top:3px}.outing-head a{font-size:12px;color:#2563eb;white-space:nowrap}.outing-head>small{font-size:11px;color:#6b6086}.sample-note{font-size:10px;color:#8c789b;line-height:1.5;margin-top:-5px}.companion-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.companion-grid button{display:flex;align-items:center;gap:8px;min-height:76px;padding:8px;border:2px solid #e7ddf3;border-radius:16px;background:#ffffffe0;text-align:left;color:#2b2340}.companion-grid button[aria-checked=true]{border-color:#2563eb;background:#fff;box-shadow:0 6px 16px #4f8cff24}.companion-grid img{width:45px;height:45px;object-fit:cover;border-radius:50%;flex:none}.companion-grid button>span{display:flex;flex-direction:column;min-width:0;line-height:1.4}.companion-grid b{font-size:14px}.companion-grid small{font-size:10px;color:#6b6086;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.companion-grid em{font-style:normal;font-size:11px;color:#8b7b99}.companion-grid [aria-checked=true] em{color:#2563eb;font-weight:600}.scene-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.scene-grid button{display:flex;flex-direction:column;position:relative;padding:5px 5px 8px;border:2px solid transparent;border-radius:16px;overflow:hidden;text-align:left;min-width:0;color:#2b2340}.scene-grid button[aria-checked=true]{border-color:#2563eb;box-shadow:0 5px 12px #4f8cff22}.scene-grid img{width:100%;height:64px;object-fit:cover;border-radius:10px}.scene-grid b{font-size:12px;margin:5px 3px 0}.scene-grid small{font-size:10px;color:#6b6086;margin:0 3px}.scene-check{position:absolute;top:9px;right:8px;border-radius:12px;background:#2563eb;color:#fff;font-size:9px;padding:2px 6px}.draft-badge{font-size:11px;padding:4px 9px;background:#dcebff;color:#2563eb;border-radius:20px}.city-field,.date-grid label{display:flex;flex-direction:column;gap:6px;color:#5a5070;font-size:12px}.city-field select,.date-grid input{width:100%;min-width:0;padding:10px 8px;border-radius:12px;border:1px solid #d6c9e5;background:#ffffffe0;color:#2b2340;font:inherit;min-height:43px}.date-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:8px}.plan-summary{display:flex;flex-direction:column;gap:8px;margin:0;padding:12px;border-radius:15px;background:#ffffff99}.plan-summary>div{display:flex;gap:12px;font-size:12px}.plan-summary dt{color:#6b6086;white-space:nowrap}.plan-summary dd{margin:0;flex:1;text-align:right;overflow-wrap:anywhere}.route-heading{display:flex;justify-content:space-between;align-items:center}.plan-card h3{font-size:14px;font-weight:600}.route-heading span{font-size:10px;color:#8d7a9e}.outing-route{list-style:none;margin:0;padding:12px;border-radius:16px;background:#ffffffb8}.outing-route li{display:flex;align-items:flex-start;gap:10px;position:relative;padding-bottom:20px}.outing-route li:last-child{padding-bottom:0}.outing-route li:not(:last-child):before{content:'';position:absolute;left:11px;top:23px;bottom:0;border-left:1px dashed #b8a3cc}.outing-route li>span{width:23px;height:23px;display:grid;place-items:center;background:#ebe3ff;color:#7654ac;border-radius:50%;font-size:11px;flex:none}.outing-route li b,.outing-route li small{display:block}.outing-route li b{font-size:12px}.outing-route li small{font-size:10px;color:#8b7b99;line-height:1.5;margin-top:3px}.route-empty{font-size:12px;padding:20px;color:#8b7b99;background:#ffffff99;border-radius:16px}.packing-list{display:flex;gap:6px;flex-wrap:wrap}.packing-list button{border:1px solid #e7ddf3;border-radius:20px;padding:7px 9px;background:white;color:#8b7b99;font-size:11px}.packing-list button[aria-pressed=true]{color:#2563eb;background:#dcebff;border-color:#9db8f2}.plan-note{font-size:10px;color:#8b7b99;text-align:center;line-height:1.5}.cancel-edit{border:0;background:transparent;color:#8b6cc9;font-size:12px}.history-entry{display:flex;align-items:center;gap:8px;border:1px solid white;border-radius:18px;padding:15px;background:#ffffffb8;color:#5a5070;font-size:14px}.history-entry span{margin-left:auto;font-size:12px;color:#2563eb}.outing-page footer{font-size:11px;text-align:center;color:#8b7b99;line-height:1.7}.trip-history{padding:28px 22px 40px;color:#2b2340}.trip-history h2{font-size:21px}.trip-history>p{font-size:12px;color:#8b7b99;margin:4px 0 20px}.saved-trip{padding:16px;border:1px solid #e7ddf3;border-radius:18px;background:#f8f5fd;margin-bottom:14px}.saved-tag{font-size:10px;color:#8b6cc9}.saved-trip h3{font-size:15px;margin:5px 0}.saved-trip p{font-size:12px;color:#6b6086}.saved-route{margin:8px 0}.saved-trip small{font-size:10px;color:#8b7b99}.saved-actions{display:flex;gap:8px;margin-top:14px}.saved-actions button{border:1px solid #d6c9e5;background:white;border-radius:12px;padding:7px 12px;font-size:12px;color:#7654ac}@media(max-width:350px){.outing-card{padding:12px}.companion-grid img{width:36px;height:36px}.scene-grid img{height:56px}}
</style>
